"""Palindrome Partitioning II — expand-around-center to fill the cut table.

Growing palindromes outward from every center updates cuts[right] directly, so
no separate O(n^2) palindrome table is needed.

Time: O(n^2)   Space: O(n)
"""


class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        cuts = list(range(-1, n))          # cuts[i] = min cuts for s[:i]
        for center in range(n):
            for lo, hi in ((center, center), (center, center + 1)):
                while lo >= 0 and hi < n and s[lo] == s[hi]:
                    cuts[hi + 1] = min(cuts[hi + 1], cuts[lo] + 1)
                    lo -= 1
                    hi += 1
        return cuts[n]
